import React, { useState } from "react";
import "./App.css";

function App() {
  const [disease, setDisease] = useState("");
  const [intent, setIntent] = useState("");
  const [location, setLocation] = useState("");
  const [whatIf, setWhatIf] = useState("");

  const [loading, setLoading] = useState(false);
  const [data, setData] = useState(null);
  const [error, setError] = useState("");

  const handleSubmit = async (e) => {
    e.preventDefault(); // ✅ prevents reload

    setLoading(true);
    setError("");
    setData(null);

    try {
      const res = await fetch("http://localhost:5000/api/query", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          disease,
          intent,
          location,
          what_if: whatIf,
        }),
      });

      const result = await res.json();

      console.log("FRONTEND DATA:", result); // ✅ debug

      setData(result);
    } catch (err) {
      console.error(err);
      setError("⚠️ Failed to fetch AI insights");
    } finally {
      setLoading(false); // ✅ stops loading
    }
  };

  return (
    <div className="container">
      <h1>🧠 AI Medical Research Assistant</h1>

      <form onSubmit={handleSubmit}>
        <input
          type="text"
          placeholder="Enter disease (e.g. diabetes)"
          value={disease}
          onChange={(e) => setDisease(e.target.value)}
          required
        />

        <input
          type="text"
          placeholder="Enter intent (e.g. treatment)"
          value={intent}
          onChange={(e) => setIntent(e.target.value)}
        />

        <input
          type="text"
          placeholder="Enter location (e.g. USA)"
          value={location}
          onChange={(e) => setLocation(e.target.value)}
        />

        <input
          type="text"
          placeholder="What If scenario (e.g. age > 60)"
          value={whatIf}
          onChange={(e) => setWhatIf(e.target.value)}
        />

        {/* ✅ ONLY submit button (no onClick) */}
        <button type="submit">
          {loading ? "Analyzing..." : "Analyze"}
        </button>
      </form>

      {error && <p className="error">{error}</p>}

      {/* ✅ RESULT SECTION */}
      {data && (
        <div className="result">
          <h2>📊 AI Insights</h2>

          {data.summary && (
            <p>
              <strong>Summary:</strong> {data.summary}
            </p>
          )}

          {data.what_if && (
            <>
              <h3>🔍 What If Analysis</h3>
              <p>{data.what_if}</p>
            </>
          )}
        </div>
      )}
    </div>
  );
}

export default App;
